CREATE OR REPLACE PROCEDURE HARNESS_APP.archive_old_orders (p_date IN DATE) AS
  TYPE t_orders IS TABLE OF HARNESS_APP.ORDERS%ROWTYPE;
  l_batch t_orders;

  CURSOR c_old_orders IS
    SELECT *
      FROM HARNESS_APP.ORDERS
     WHERE ORDER_DATE < p_date;
BEGIN
  OPEN c_old_orders;

  LOOP
    FETCH c_old_orders BULK COLLECT INTO l_batch LIMIT 10000;
    EXIT WHEN l_batch.COUNT = 0;

    FORALL i IN INDICES OF l_batch
      INSERT INTO HARNESS_APP.ORDERS_ARCHIVE
        (ORDER_ID, CUSTOMER_ID, ORDER_DATE, STATUS, TOTAL)
      VALUES
        (l_batch(i).ORDER_ID,
         l_batch(i).CUSTOMER_ID,
         l_batch(i).ORDER_DATE,
         l_batch(i).STATUS,
         l_batch(i).TOTAL);

    FORALL i IN INDICES OF l_batch
      DELETE FROM HARNESS_APP.ORDERS
       WHERE ORDER_ID = l_batch(i).ORDER_ID;
  END LOOP;

  CLOSE c_old_orders;
END archive_old_orders;
