      SELECT COUNT(*)
        INTO l_expected
        FROM employees
       WHERE department_id = l_department_id;

      l_actual := HARNESS_APP.headcount(l_department_id);

      IF l_actual = l_expected THEN
        DBMS_OUTPUT.PUT_LINE('PASS: headcount for matching department_id ' ||
