                             ' returned ' || TO_CHAR(l_actual) ||
                             ', expected ' || TO_CHAR(l_expected) || '.');
        l_failures := l_failures + 1;
      END IF;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('FAIL: matching-key setup or check raised an error: ' || SQLERRM);
      l_failures := l_failures + 1;
  END;

  -- Check 2: a non-NULL department_id that should match no rows.
  BEGIN
    SELECT COUNT(*)
      INTO l_no_match_rows
      FROM employees
     WHERE department_id = l_no_match_id;

    IF l_no_match_rows <> 0 THEN
      DBMS_OUTPUT.PUT_LINE('FAIL: no-match setup found rows for department_id ' ||
