      l_failures := l_failures + 1;
    ELSE
      l_expected := 0;
      l_actual := HARNESS_APP.headcount(l_no_match_id);

      IF l_actual = l_expected THEN
        DBMS_OUTPUT.PUT_LINE('PASS: headcount for no-match department_id ' ||
