    IF l_actual = l_expected THEN
      DBMS_OUTPUT.PUT_LINE('PASS: headcount for NULL department_id returned expected count ' ||
                           TO_CHAR(l_expected) || '.');
    ELSE
      DBMS_OUTPUT.PUT_LINE('FAIL: headcount for NULL department_id returned ' ||
